cypress_script:
describe('Asynchronously Loaded Content', () => {
  it('should display the content after clicking Start', () => {
    cy.visit('https://the-internet.herokuapp.com/dynamic_loading/1');
    cy.get('div#start button').click();
    cy.get('div#finish').should('be.visible');
  });

  it('should not display the content before clicking Start', () => {
    cy.visit('https://the-internet.herokuapp.com/dynamic_loading/1');
    cy.get('div#finish').should('not.be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Asynchronously Loaded Content', () => {
  test('should display the content after clicking Start', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dynamic_loading/1');
    await page.click('div#start button');
    await expect(page.locator('div#finish')).toBeVisible();
  });

  test('should not display the content before clicking Start', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dynamic_loading/1');
    await expect(page.locator('div#finish')).not.toBeVisible();
  });
});
